{"cards": [{"node_code": "N_955d98ff3faacfb2", "definition": "研究视觉功能评估、屈光状态分析及光学矫正手段的学科，涵盖验光、眼镜及角膜接触镜的适配与视觉康复。", "boundary": "聚焦于非手术性的视觉矫正与功能评估，包括主观/客观验光、双眼视功能检查、低视力康复及各类光学镜片（框架、隐形）的验配。不包含眼球器质性病变的药物治疗或手术干预，也不包含以改变眼球形态为目的的屈光手术（如LASIK）。", "includes": ["屈光不正的诊断与验光配镜", "角膜接触镜的验配与护理", "双眼视功能异常及视觉康复训练"], "excludes": ["屈光手术（如LASIK、ICL植入）", "眼球器质性疾病的临床治疗"], "sibling_distinctions": [{"other_code": "N_6c65ea1c27297414", "rule": "眼前节疾病侧重角膜、虹膜等组织的病理改变；视光学侧重屈光状态评估及光学矫正手段。"}, {"other_code": "N_260707270aa8a0c7", "rule": "眼表疾病侧重结膜、泪膜等表面组织的炎症或损伤；视光学侧重屈光矫正及视觉功能。"}], "cross_boundary_rule": "若屈光不正由眼部疾病（如白内障早期）引起，主挂相应疾病节点；若仅为生理性屈光变化或需光学矫正，主挂视光学。"}, {"node_code": "N_e1bd931cce38839b", "definition": "研究视神经结构、功能及其相关疾病（如视神经炎、缺血性视神经病变、遗传性视神经病变）的医学分支。", "boundary": "涵盖视神经的解剖生理、常见病因（炎症、缺血、压迫、中毒、遗传）及诊疗。若视神经病变由眼部疾病（如青光眼、葡萄膜炎）直接引起，主挂相应眼科疾病节点；若由脑部肿瘤、脱髓鞘疾病（如多发性硬化）等中枢神经系统病变引起，主挂神经病学。", "includes": ["视神经炎及缺血性视神经病变", "遗传性及中毒性视神经病变", "视神经压迫性病变的眼科评估"], "excludes": ["由脑部肿瘤或脱髓鞘疾病主导的视神经病变（主挂神经病学）", "由青光眼或葡萄膜炎直接引起的视神经损害（主挂相应疾病节点）"], "sibling_distinctions": [{"other_code": "N_d59f345288e687ab", "rule": "青光眼侧重眼压升高及视神经损害机制；视神经疾病侧重视神经本身的炎症、缺血或遗传病变。"}, {"other_code": "N_9b946b5b9c7cd74e", "rule": "葡萄膜疾病侧重脉络膜、睫状体等炎症；视神经疾病侧重视神经本身的病变。"}], "cross_boundary_rule": "视神经病变若由眼部疾病（如青光眼、炎症）引起，主挂本节点；若由脑部肿瘤、脱髓鞘等引起，主挂神经病学。"}, {"node_code": "N_d59f345288e687ab", "definition": "研究以眼压升高和视神经损害为特征的青光眼疾病的发病机制、诊断、治疗及预防的医学分支。", "boundary": "涵盖原发性开角型、闭角型青光眼及继发性青光眼的临床诊疗，包括眼压控制、视功能保护及手术干预。不包含非青光眼引起的视神经病变（如视神经炎），也不包含单纯的眼压测量技术（归入视光学或眼科检查）。", "includes": ["原发性开角型与闭角型青光眼", "继发性青光眼及先天性青光眼", "青光眼的手术及药物治疗"], "excludes": ["非青光眼引起的视神经病变（如视神经炎）", "单纯的眼压测量技术（归入视光学或眼科检查）"], "sibling_distinctions": [{"other_code": "N_e1bd931cce38839b", "rule": "青光眼侧重眼压升高及视神经损害机制；视神经疾病侧重视神经本身的炎症、缺血或遗传病变。"}, {"other_code": "N_6c65ea1c27297414", "rule": "眼前节疾病侧重角膜、虹膜等组织的病理改变；青光眼侧重眼压及视神经损害。"}], "cross_boundary_rule": "青光眼引起的视神经损害主挂本节点；非青光眼引起的视神经病变主挂视神经疾病。"}]}
